"""User-owned reference folders; paths are generated by the server."""
from contextlib import closing
from uuid import uuid4

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel, Field

from app.api.auth import CurrentUser
from app.models import db
from app.services.library_service import owned_folder, now
from app.services.storage_service import UPLOAD_DIR

router = APIRouter(prefix='/api/library', tags=['示例图库'])


class FolderName(BaseModel):
    name: str = Field(min_length=1, max_length=120)


@router.get('/folders')
def list_folders(user: CurrentUser):
    with closing(db.get_connection()) as con:
        rows = con.execute('''SELECT f.*, COUNT(a.asset_id) AS image_count FROM reference_folders f
            LEFT JOIN assets a ON a.folder_id=f.folder_id AND a.user_id=f.user_id AND a.deleted_at IS NULL
            WHERE f.user_id=? GROUP BY f.folder_id ORDER BY f.created_at DESC''', (user['user_id'],)).fetchall()
    return {'items': [dict(r) for r in rows]}


@router.post('/folders', status_code=201)
def create_folder(user: CurrentUser, payload: FolderName):
    name = payload.name.strip()
    if not name:
        raise HTTPException(400, '文件夹名称不能为空')
    folder_id = uuid4().hex
    with closing(db.get_connection()) as con, con:
        if con.execute('SELECT COUNT(*) FROM reference_folders WHERE user_id=?', (user['user_id'],)).fetchone()[0] >= 1000:
            raise HTTPException(400, '文件夹数量已达1000个')
        path = UPLOAD_DIR / 'references' / folder_id
        path.mkdir(parents=True, exist_ok=False)
        try:
            con.execute('INSERT INTO reference_folders VALUES (?,?,?,?,?)', (folder_id, user['user_id'], name, None, now()))
        except Exception:
            path.rmdir()
            raise
    return owned_folder(folder_id, user['user_id'])


@router.get('/folders/{folder_id}/assets')
def folder_assets(folder_id: str, user: CurrentUser, page: int = Query(1, ge=1), page_size: int = Query(60, ge=1, le=100)):
    if folder_id != 'unfiled':
        owned_folder(folder_id, user['user_id'])
    folder_clause = 'folder_id IS NULL' if folder_id == 'unfiled' else 'folder_id=?'
    args = [user['user_id']] + ([] if folder_id == 'unfiled' else [folder_id])
    where = f"user_id=? AND role='reference' AND deleted_at IS NULL AND {folder_clause}"
    with closing(db.get_connection()) as con:
        total = con.execute('SELECT COUNT(*) FROM assets WHERE ' + where, args).fetchone()[0]
        rows = con.execute('SELECT asset_id,filename,width,height,role,folder_id,source_url FROM assets WHERE '
                           + where + ' ORDER BY created_at DESC,asset_id DESC LIMIT ? OFFSET ?',
                           [*args, page_size, (page-1)*page_size]).fetchall()
    return {'items': [{**dict(r), 'preview_url': f"/api/assets/{r['asset_id']}/preview"} for r in rows],
            'total': total, 'page': page, 'page_size': page_size}
